function isTaiwanIdNo(n){if(!/^([A-Z])[1,2]\d{8}$/.test(n))return!1;const t=`${countryCodes.indexOf(n[0])}${n.substring(1)}`,i=[...t].reduce((n,t,i)=>n+t*weights[i],0);return i%10==0}function isNewTaiwanResidentCertificateNo(n){if(!/^([A-Z])[8,9]\d{8}$/.test(n))return!1;const t=`${countryCodes.indexOf(n[0])}${n.substring(1)}`,i=[...t].reduce((n,t,i)=>n+t*weights[i],0);return i%10==0}function isOldTaiwanResidentCertificateNo(n){if(!/^([A-Z])([A-D])\d{8}$/.test(n))return!1;const t=`${countryCodes.indexOf(n[0])}${countryCodes.indexOf(n[1])%10}${n.substring(2)}`,i=[...t].reduce((n,t,i)=>n+t*weights[i],0);return i%10==0}function isTaiwanResidentCertificateNo(n){return isNewTaiwanResidentCertificateNo(n)||isOldTaiwanResidentCertificateNo(n)}const countryCodes="0123456789ABCDEFGHJKLMNPQRSTUVXYWZIO",weights=[1,9,8,7,6,5,4,3,2,1,1];